  function R(id, itemType, jp, mnPassage, enPassage, ask, options, correct, explain) {
    return {
      id: id, level: "N2", itemType: itemType,
      passage: { jp: jp, kana: kanaLookup[id] || "", translation: locale(mnPassage, enPassage, jp) },
      ask: ask, options: options, correct: correct, explain: explain
    };
  }
  function L(id, itemType, turns, audio, mn, en, ask, options, correct, explain) {
    var dialogue = turns.map(function (text, index) {
      var a = index % 2 === 0;
      return { speaker: locale(a ? "А" : "Б", a ? "A" : "B", a ? "A" : "B"), text: text };
    });
    return { id: id, level: "N2", itemType: itemType, dialogue: dialogue, audio: audio,
      kana: kanaLookup[id] || "", translation: locale(mn, en, audio), ask: ask, options: options, correct: correct, explain: explain };
  }

  /* Existing N2 prompts are classified into the official purpose categories. */
